/* eslint-disable react/prop-types */
import React, { useEffect, useState, useMemo } from 'react';
import { Helmet } from 'react-helmet-async';
import { useNavigate, useLocation } from 'react-router-dom';
import {
  Card,
  Table,
  Stack,
  Paper,
  Avatar,
  Button,
  Popover,
  TableRow,
  MenuItem,
  TableBody,
  TableCell,
  Typography,
  IconButton,
  TableContainer,
  TablePagination,
  Box,
} from '@mui/material';
import { axios } from '../utils/axios';
import { IMAGE_URL } from '../utils/config';
import { updateUrlParams } from '../utils/urlUtilis';
// components
import Iconify from '../components/iconify';
import Scrollbar from '../components/scrollbar';
// sections
import { UserListHead, UserListToolbar } from '../sections/@dashboard/user';
import { useMyContext } from './provider';
import GenerateToastConfig from '../components/toast-config/GenerateToastConfig';
import useResponsive from '../hooks/useResponsive';
import DeleteModal from '../components/deleteModal/DeleteModal';
import TanstackTable from '../components/tanstackMUItable/TanstackTable';
import TanstackTableV8 from '../components/tanstackMUItable/tanstackTableV8';

export default function UserPage() {
  const navigate = useNavigate();
  const location = useLocation();
  const queryParams = new URLSearchParams(location.search)
  const [deleteOpens, setDeleteOpens] = useState(false);
  const [open, setOpen] = useState(null);
  const [page, setPage] = useState(parseInt(queryParams.get('page'), 10) || 1);
  const [order, setOrder] = useState('asc');
  const [selected, setSelected] = useState([]);
  const [orderBy, setOrderBy] = useState('name');
  const [filterName, setFilterName] = useState('');
  const [rowsPerPage, setRowsPerPage] = useState(parseInt(queryParams.get('limit'), 5) || 5);
  const [propertyList, setPropertyList] = React.useState([]);
  const [totalCount, setTotalCount] = useState(0);
  const [filters, setFilters] = useState({});
  const [isLoading, setIsLoading] = useState(true);


  const { i18 } = useMyContext();
  const isMobile = useResponsive('down', 'sm')
  const queryPrms = new URLSearchParams(location.search);
  const id = queryPrms.get("id")
  const TABLE_HEAD = [
    { id: 'property', label: i18?.LISTINGPAGE?.PROPERTY_NAME || 'PROPERTY_NAME', alignRight: false },
    { id: 'desc', label: i18?.LISTINGPAGE?.PROPERTY_DESCRIPTION || 'PROPERTY_DESCRIPTION', alignRight: false },
    { id: 'icon', label: i18?.LISTINGPAGE?.ICON || 'ICON', alignRight: false },
    { id: 'action', label: i18?.LISTINGPAGE?.ACTION || 'ACTION', alignRight: false },
  ];

  const fetchData = async () => {
    setIsLoading(true);
    try {
      const res = await axios.get(`module/admin/property/${id}?_limit=${rowsPerPage}&_page=${page}`);
      if (res.status === 200) {
        setPropertyList(res.data.data.properties);
        setTotalCount(res.data.data.totalCount);
      } else {
        GenerateToastConfig(res.data.message);
      }
    } catch (err) {
      GenerateToastConfig(err?.response?.data?.message);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, [page, rowsPerPage, order, orderBy, filters]);

  useEffect(() => {
    updateUrlParams({ page, limit: rowsPerPage });
  }, [page, rowsPerPage]);

  const ActionComponent = (cell) => {
    const value = cell?.getValue();
    const original = cell?.row?.original;
    const [anchorEl, setAnchorEl] = useState(null);
    const [menuRowId, setMenuRowId] = useState(null);

    const handleActionMenu = (event, rowId) => {
      setAnchorEl(event.currentTarget);
      setMenuRowId(rowId);
    };

    const handleActionMenuClose = () => {
      setAnchorEl(null);
      setMenuRowId(null);
    };

    return (
      <>
        <IconButton
          sx={{
            width: '37px',
            height: '37px',
            background: '#EBEBEB',
            color: 'black',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            borderRadius: '50%',
          }}
          onClick={(event) => handleActionMenu(event, value)}
        >
          <Iconify icon="mdi:dots-horizontal" />
        </IconButton>
        <Popover
          anchorEl={anchorEl}
          open={Boolean(anchorEl) && menuRowId === value}
          onClose={handleActionMenuClose}
          anchorOrigin={{ vertical: 'top', horizontal: 'left' }}
          transformOrigin={{ vertical: 'top', horizontal: 'right' }}
          PaperProps={{
            sx: { width: 140 },
          }}
        >
          <MenuItem onClick={() => editproperty(value, original?.property, original?.desc, original?.icon, cate)}>
            <Iconify icon={'carbon:edit'} sx={{ mr: 2 }} /> Edit
          </MenuItem>
          <MenuItem onClick={() => deleteModal(value)} sx={{ color: 'error.main' }}>
            <Iconify icon={'eva:trash-2-outline'} sx={{ mr: 2 }} /> Delete
          </MenuItem>
        </Popover>
      </>
    );
  }

  const columns = [
    {
      header: i18?.LISTINGPAGE?.PROPERTY_NAME || 'PROPERTY_NAME',
      id: "property",
      accessorKey: "property",
      showFilter: false,
      cell: ({ row }) => (row?.original?.property || "---")
    },
    {
      header: i18?.LISTINGPAGE?.PROPERTY_DESCRIPTION || 'PROPERTY_DESCRIPTION',
      id: "desc",
      accessorKey: "desc",
      cell: ({ row }) => (row?.original?.desc || "---")
    },
    {
      header: i18?.LISTINGPAGE?.ICON || 'ICON',
      id: "icon",
      accessorKey: "icon",
      cell: ({ row }) => (
        row?.original?.icon ? <Avatar variant="square" src={IMAGE_URL + row?.original?.icon} sx={{ width: 40, height: 40 }} /> : "---"
      )
    },
    {
      header: i18?.SETTINGSLIST?.ACTION || "Action",
      id: "action",
      accessorKey: "_id",
      cell: ActionComponent,
    },
  ];

  if (!location && !location?.state)
    return null;
  const { cate } = location?.state || { cate: '' };

  const deleteModal = (ids) => {
    sessionStorage.setItem("userId", ids)
    setDeleteOpens(true);
  }

  const deleteAmenity = async () => {
    const ids = sessionStorage.getItem("userId")
    try {
      const res = await axios.delete(`module/admin/property/${ids}`);
      if (res.status === 200) {
        setDeleteOpens(false)
        GenerateToastConfig('Property Deleted', 'info');
        fetchData();
      } else {
        GenerateToastConfig(res.data.message);
      }
    } catch (err) {
      GenerateToastConfig(err?.response?.data?.message);
    }
  };

  const handleCloseMenu = () => {
    setOpen(null);
  };

  const handleRequestSort = (event, property) => {
    const isAsc = orderBy === property && order === 'asc';
    setOrder(isAsc ? 'desc' : 'asc');
    setOrderBy(property);
  };

  const handleSelectAllClick = (event) => {
    if (event.target.checked) {
      const newSelecteds = propertyList.map((n) => n.name);
      setSelected(newSelecteds);
      return;
    }
    setSelected([]);
  };

  const handleOpenModal = () => {
    const type = 'Property';
    const action = 'Add';
    navigate('/dashboard/addamenity', { state: { types: type, process: action, ids: id, categories: cate } });
  };

  const handleChangePage = (event, newPage) => {
    setPage(newPage + 1);
  };

  const handleChangeRowsPerPage = (event) => {
    setPage(1);
    setRowsPerPage(parseInt(event.target.value, 10));
  };

  const handleFilterByName = (event) => {
    setPage(0);
    setFilterName(event.target.value);
  };

  const editproperty = (ids, property, description, icon) => {
    navigate(`/dashboard/EditProperty/${ids}`, { state: { proids: id, pro: property, desc: description, img: icon, cate, _id: ids } });
  }

  const handleFilterChange = (filterKey, value) => {
    setFilters((prev) => ({ ...prev, [filterKey]: value }));
    setPage(1);
  };

  const backToRoute = () => {
    navigate('/dashboard/category')
  }

  return (
    <>
      <Helmet>
        <title> {"List Amenity | Admin panel"} </title>
      </Helmet>

      {isMobile &&
        <Stack direction='row' alignItems='center' style={{ marginBottom: '30px' }} justifyContent='space-between'>
          <Box sx={{ display: 'flex', alignItems: 'center' }}>
            <Box
              sx={{
                width: '37px',
                height: '37px',
                background: '#FF5A60',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                borderRadius: '50%',
                cursor: 'pointer',
              }}
              onClick={backToRoute}
            >
              <Iconify icon={'mdi:arrow-left'} width={24} height={24} color="white" />
            </Box>
            <Typography className="text-capitalize" variant="h4" gutterBottom sx={{ margin: '0px 0px 0px 10px', paddingBottom: '0px' }}>
              {i18?.LISTINGPAGE?.LIST_PROPERTY || "List Property"}
            </Typography>
          </Box>
          <Button variant="contained" width='100%' onClick={handleOpenModal} startIcon={<Iconify icon="eva:plus-fill" />}>
            {i18?.LISTINGPAGE?.ADD_PROPERTY || "Add Property"}
          </Button>
        </Stack>}

      {!isMobile &&
        <Stack direction="row" alignItems="center" justifyContent="space-between" mb={5}>
          <Box sx={{ display: 'flex', alignItems: 'center' }}>
            <Box
              sx={{
                width: '37px',
                height: '37px',
                background: '#FF5A60',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                borderRadius: '50%',
                cursor: 'pointer',
              }}
              onClick={backToRoute}
            >
              <Iconify icon={'mdi:arrow-left'} width={24} height={24} color="white" />
            </Box>
            <Typography className="text-capitalize" variant="h4" gutterBottom sx={{ margin: '0px 0px 0px 10px', paddingBottom: '0px' }}>
              {i18?.LISTINGPAGE?.LIST_PROPERTY || "List Property"}
            </Typography>
          </Box>
          <Stack direction='row' alignItems='center'>
            <UserListToolbar numSelected={selected.length} filterName={filterName} onFilterName={handleFilterByName} />
            <Button variant="contained" onClick={handleOpenModal} startIcon={<Iconify icon="eva:plus-fill" />}>
              {i18?.LISTINGPAGE?.ADD_PROPERTY || "Add Property"}
            </Button>
          </Stack>
        </Stack>}

      <Card>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          {isMobile && <UserListToolbar numSelected={selected.length} filterName={filterName} onFilterName={handleFilterByName} />}
        </div>
        <Scrollbar>
          <TanstackTableV8
            data={propertyList}
            columns={columns}
            filters={filters}
            isLoading={isLoading}
            onFilterChange={handleFilterChange}
          />

        </Scrollbar>

      </Card>

      <TablePagination
        rowsPerPageOptions={[5, 10, 25]}
        component="div"
        count={totalCount || '0'}
        rowsPerPage={rowsPerPage}
        page={page - 1}
        onPageChange={handleChangePage}
        onRowsPerPageChange={handleChangeRowsPerPage}
        sx={{
          '.MuiTablePagination-selectLabel': {
            marginTop: '12px',
          },
          '.MuiTablePagination-displayedRows': {
            marginTop: '12px',
          },
          '.MuiTablePagination-actions': {
            marginBottom: '6px',
          }
        }}
      />

      <Popover
        open={Boolean(open)}
        anchorEl={open}
        onClose={handleCloseMenu}
        anchorOrigin={{ vertical: 'top', horizontal: 'left' }}
        transformOrigin={{ vertical: 'top', horizontal: 'right' }}
        PaperProps={{
          sx: {
            p: 1,
            width: 140,
            '& .MuiMenuItem-root': {
              px: 1,
              typography: 'body2',
              borderRadius: 0.75,
            },
          },
        }}
      >
        <MenuItem>
          <Iconify icon={'eva:edit-fill'} sx={{ mr: 2 }} />
          {i18?.LISTINGPAGE?.EDIT || "Edit"}
        </MenuItem>

        <MenuItem sx={{ color: 'error.main' }}>
          <Iconify icon={'eva:trash-2-outline'} sx={{ mr: 2 }} />
          {i18?.LISTINGPAGE?.DELETE || "Delete"}
        </MenuItem>
      </Popover>

      <DeleteModal
        isDeleteOpen={deleteOpens}
        handleClose={() => setDeleteOpens(false)}
        handleDelete={deleteAmenity}
      />

    </>
  );
}
